@page "/dashboard"
@implements IDisposable
@inject Services.WarehouseStateService WarehouseState
@inject Services.InventoryAlertService AlertService
@rendermode InteractiveServer

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Currently viewing: @GetWarehouseName()
        </h5>
        <p class="card-text">
            Warehouse ID: <code>@WarehouseState.CurrentWarehouseId</code>
        </p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card text-bg-@(AlertService.CurrentLowStockCount > 5 ? "danger" : AlertService.CurrentLowStockCount > 0 ? "warning" : "success")">
            <div class="card-body text-center">
                <h2>@AlertService.CurrentLowStockCount</h2>
                <p class="mb-0">Low-Stock Items</p>
            </div>
        </div>
    </div>
    <div class="col-md-8">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Alert Status</h5>
                <p>Polling is <strong>active</strong> — refreshing every 10 seconds.</p>
                <p class="text-muted mb-0">
                    Last check returned @AlertService.CurrentLowStockCount item(s) below minimum stock level.
                </p>
            </div>
        </div>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        // Subscribe to notifications so this component re-renders when alert data changes
        AlertService.OnAlertDataChanged += HandleAlertDataChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;

        // Start polling when dashboard becomes visible
        AlertService.StartPolling();
    }

    private async Task HandleAlertDataChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private void HandleWarehouseChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetWarehouseName()
    {
        var wh = Services.WarehouseStateService.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.CurrentWarehouseId);
        return wh.Name ?? WarehouseState.CurrentWarehouseId;
    }

    public void Dispose()
    {
        AlertService.OnAlertDataChanged -= HandleAlertDataChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;

        // Stop polling when user leaves the dashboard page
        AlertService.StopPolling();
    }
}

